                stack=[(i,j)]
                while stack:
                    y,x=stack.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(a) and 0<=nx<len(a[0]) and not seen[ny,nx] and a[ny,nx]==v:
